<?php
namespace App\Services;
use App\Models\TrainingSession;
use Illuminate\Validation\ValidationException;
use Illuminate\Support\Carbon;
class SessionWorkflow {
 public function ensureNoConflict(array $data, ?int $ignoreId=null): void { $start=Carbon::parse($data['session_date'].' '.$data['start_time']); $end=isset($data['end_time'])&&$data['end_time']?Carbon::parse($data['session_date'].' '.$data['end_time']):$start->copy()->addHour(); if($end->lessThanOrEqualTo($start))throw ValidationException::withMessages(['end_time'=>'End time must be after start time.']); $conflict=TrainingSession::where('athlete_id',$data['athlete_id'])->whereDate('session_date',$data['session_date'])->whereIn('status',['scheduled','in_progress'])->when($ignoreId,fn($q)=>$q->whereKeyNot($ignoreId))->get()->contains(function($s)use($start,$end){$otherStart=Carbon::parse($s->session_date->toDateString().' '.$s->start_time);$otherEnd=$s->end_time?Carbon::parse($s->session_date->toDateString().' '.$s->end_time):$otherStart->copy()->addHour();return $start->lt($otherEnd)&&$end->gt($otherStart);}); if($conflict)throw ValidationException::withMessages(['session_date'=>'This athlete already has a session during that time.']); }
 public function transition(TrainingSession $session,string $to,?array $log=null): TrainingSession { $allowed=['scheduled'=>['in_progress','missed','cancelled'],'in_progress'=>['completed']]; if(!in_array($to,$allowed[$session->status]??[],true))throw ValidationException::withMessages(['status'=>'That status change is not allowed.']); if($to==='missed'&&now()->lt(Carbon::parse($session->session_date->toDateString().' '.$session->start_time)))throw ValidationException::withMessages(['status'=>'A session can be marked missed after its start time.']); if($to==='completed'){if(!$log)throw ValidationException::withMessages(['duration_minutes'=>'Performance details are required to complete a session.']);$session->fill($log);} $session->status=$to;$session->save();return $session->load(['athlete','trainingType','creator','reviewer']); }
}
